import * as THREE from 'three';
const host=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({antialias:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.45));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;host.appendChild(renderer.domElement);
const scene=new THREE.Scene();scene.background=new THREE.Color(0x101715);scene.fog=new THREE.FogExp2(0x101715,.008);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,550);camera.position.set(0,49,66);camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight(0xc9d8d0,0x272b27,1.7));const key=new THREE.DirectionalLight(0xe4f0e2,1.45);key.position.set(-34,65,20);scene.add(key);
const mat=(color,emissive=0x000000,emissiveIntensity=0)=>new THREE.MeshStandardMaterial({color,roughness:.96,metalness:.02,emissive,emissiveIntensity});
const groundMat=mat(0x343936), roadMat=mat(0x202522), pale=mat(0xaaaead,0x777c7a,.18), dark=mat(0x171b1a), hot=mat(0xe8edeb,0xbec5c2,.68), enemyMat=mat(0x525957,0x919894,.28), allyMat=mat(0x767d79,0xc0c8c3,.3), lightMat=mat(0xe1e7e4,0xffffff,2.4), redMat=mat(0xc2c5c2,0xf3eeee,1.6);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(260,260,32,32),groundMat);floor.rotation.x=-Math.PI/2;floor.position.y=-1;scene.add(floor);
// Low-poly ridgelines and terrain silhouettes.
for(let r=0;r<3;r++)for(let i=0;i<11;i++){const h=7+Math.random()*14,w=12+Math.random()*19;const m=new THREE.Mesh(new THREE.ConeGeometry(w,h,5),mat(0x282e2b));m.position.set(-115+i*24+(Math.random()*8),h/2-1,-85-r*24);m.rotation.y=Math.random()*1.5;scene.add(m);}
// Roads run through the convoy's route and the hostile approach.
function road(points,width=4){const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(p[0],-.82,p[1])));const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,100,width/2,7,false),roadMat);scene.add(mesh);return curve;}
const route=road([[-78,32],[-50,29],[-23,20],[0,13],[25,9],[48,4],[77,-5],[102,-14]],5.8);
road([[-52,-62],[-38,-43],[-17,-25],[2,-9],[25,8],[42,28],[62,52]],3.2);
// sparse broken shoulders and runway-like lane markings
for(let i=0;i<18;i++){const p=route.getPointAt(i/17);const d=new THREE.Mesh(new THREE.BoxGeometry(.22,.04,2.2),mat(0x676c68));d.position.set(p.x,-.77,p.z);d.rotation.y=Math.atan2(route.getTangentAt(i/17).x,route.getTangentAt(i/17).z);scene.add(d);}
function box(parent,w,h,d,material,x,y,z){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);parent.add(o);return o;}
function building(x,z,w,d,h){const g=new THREE.Group();box(g,w,h,d,mat(0x474e4a),0,h/2-1,0);box(g,w*.7,.4,d*.75,dark,0,h-.7,0);for(let i=-1;i<=1;i++)box(g,.15,.55,.12,pale,i*w*.27,h*.42,d/2+.03);g.position.set(x,-.8,z);scene.add(g);return g;}
[[35,-31,9,7,5],[-31,-36,8,11,6],[66,-37,12,8,7],[-65,-3,10,7,5],[19,-48,7,8,4],[88,20,11,8,6],[-44,51,9,6,5],[4,53,13,9,7]].forEach(v=>building(...v));
// Yard tanks, antenna masts, and warm points of thermal contrast.
for(const [x,z] of [[43,-31],[47,-32],[65,-41],[71,-39],[-31,-40],[92,20]]){const tank=new THREE.Mesh(new THREE.CylinderGeometry(2,2,2.2,9),mat(0x4d5450,0x9ca39e,.2));tank.position.set(x,.3,z);scene.add(tank);const top=new THREE.Mesh(new THREE.SphereGeometry(1.7,8,5),mat(0x59605c));top.position.set(x,1.3,z);scene.add(top);}
for(const [x,z] of [[-60,35],[0,-55],[80,48],[-90,-35],[50,60]]){const pole=new THREE.Group();const stem=new THREE.Mesh(new THREE.CylinderGeometry(.13,.2,8,5),dark);stem.position.y=3;pole.add(stem);const lamp=new THREE.Mesh(new THREE.SphereGeometry(.55,7,5),lightMat);lamp.position.y=7;pole.add(lamp);pole.position.set(x,-.8,z);scene.add(pole);}
function vehicle(type,x,z,allied=false){const g=new THREE.Group();const bodyMat=allied?allyMat:enemyMat;box(g,2.5,1.1,4.2,bodyMat,0,.4,0);box(g,1.7,.6,1.8,allied?pale:dark,0,1.15,-.15);for(const s of [-1,1])for(const a of [-1.25,1.25]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.38,.38,.28,8),dark);wheel.rotation.z=Math.PI/2;wheel.position.set(s*1.25,.25,a);g.add(wheel);}if(!allied){const barrel=box(g,.15,.18,2,bodyMat,0,1.35,-1.2);barrel.rotation.x=-.04;}else{const beacon=new THREE.Mesh(new THREE.SphereGeometry(.22,7,5),lightMat);beacon.position.set(0,1.9,0);g.add(beacon);}g.position.set(x,0,z);scene.add(g);return g;}
const allies=[vehicle('truck',-12,16,true),vehicle('truck',-18,18,true),vehicle('truck',-24,20,true)];
const enemies=[];const enemySpawns=[[35,-18],[49,-29],[61,-44],[78,-22]];for(let i=0;i<4;i++){const v=vehicle('technical',...enemySpawns[i]);v.userData={hp:1,alive:true,index:i,shootClock:6+i*3};enemies.push(v);}
// Enemy compound details / sandbag ring
for(const [x,z] of [[40,-27],[73,-35]]){for(let i=0;i<7;i++){const a=i*Math.PI*2/7;const b=box(scene,.9,.8,.9,mat(0x555b58),x+Math.cos(a)*4,.0,z+Math.sin(a)*4);b.rotation.y=a;}}
const explosions=[];const shots=[];let running=false,mode='WHITE HOT',aimX=0,aimZ=0,zoom=1,weapon=0,ammo=[120,18,6],reloading=false,shotTimer=0,elapsed=0,enemyDown=0,losses=0,convoyProgress=0,fireHeld=false,fireLoop=null,audio=null,rumble=0;
const weapons=[{name:'M61 · 25 MM',desc:'HIGH RATE · LIGHT IMPACT',rate:.12,damage:1,blast:1,capacity:120,reload:4,color:0xe9f0ed,sound:180},{name:'BOFORS · 40 MM',desc:'SINGLE SHOT · MEDIUM BLAST',rate:.72,damage:1,blast:3.2,capacity:18,reload:5.5,color:0xf0f1ee,sound:115},{name:'M102 · 105 MM',desc:'HEAVY SHELL · DEVASTATING',rate:1.55,damage:1,blast:6.5,capacity:6,reload:7,color:0xffffff,sound:72}];
const shellMat=mat(0xffffff,0xffffff,2.4);function sound(freq,dur=.12,type='square',vol=.025){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(28,freq*.38),audio.currentTime+dur);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}
function radio(text){document.querySelector('#radio').textContent='“'+text+'”';}
function fireShot(){if(!running||reloading||shotTimer>0)return;if(ammo[weapon]<=0){reload();return;}ammo[weapon]--;shotTimer=weapons[weapon].rate;document.querySelector('#ammo').textContent=ammo[weapon]+' / '+weapons[weapon].capacity;sound(weapons[weapon].sound,weapon===2?.55:.13,weapon===0?'sawtooth':'triangle',weapon===2?.09:.035);if(weapon===2){rumble=.8;}else rumble=.12;
const target=enemies.filter(e=>e.userData.alive).sort((a,b)=>a.position.distanceTo(new THREE.Vector3(aimX,0,aimZ))-b.position.distanceTo(new THREE.Vector3(aimX,0,aimZ)))[0];let hit=target&&target.position.distanceTo(new THREE.Vector3(aimX,0,aimZ))<8+weapons[weapon].blast*.45;
// Friendly-fire safety: the aiming reticle will not silently ignore the convoy.
const friendly=allies.some(a=>a.visible&&a.position.distanceTo(new THREE.Vector3(aimX,0,aimZ))<4+weapons[weapon].blast*.35);
if(friendly){losses++;document.querySelector('#message').classList.add('show');radio('FRIENDLY FIRE! CHECK YOUR TARGET.');setTimeout(()=>document.querySelector('#message').classList.remove('show'),1250);if(losses>=3){allies[0].visible=false;updateIntegrity();}sound(210,.26,'sawtooth',.06);}
else if(hit){target.userData.hp-=weapons[weapon].damage;target.userData.alive=false;target.visible=false;enemyDown++;makeBlast(target.position,weapon);updateObjective();sound(weapons[weapon].sound*.55,.36,'sine',.065);if(enemyDown===4){radio('ALL HOSTILE UNITS DOWN. CONVOY, CONTINUE TO CHECKPOINT.');setTimeout(()=>finish(true),3500);}}
else{const pos=new THREE.Vector3(aimX,-.55,aimZ);makeBlast(pos,weapon,true);}
}
function makeBlast(pos,index,miss=false){const size=weapons[index].blast;const group=new THREE.Group();group.position.copy(pos);scene.add(group);const core=new THREE.Mesh(new THREE.SphereGeometry(size*.43,9,7),new THREE.MeshBasicMaterial({color:index===2?0xffffff:0xd9dedb,transparent:true,opacity:.88}));group.add(core);const ring=new THREE.Mesh(new THREE.RingGeometry(size*.45,size*.7,16),new THREE.MeshBasicMaterial({color:0xe5e8e5,transparent:true,opacity:.7,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.2;group.add(ring);const smoke=new THREE.Mesh(new THREE.SphereGeometry(size*.58,7,5),new THREE.MeshBasicMaterial({color:0x858b88,transparent:true,opacity:index===2?.47:.19}));smoke.position.y=size*.45;group.add(smoke);explosions.push({group,t:0,size,miss});}
function reload(){if(reloading||!running)return;reloading=true;const total=weapons[weapon].reload;radio('RELOADING '+weapons[weapon].name+' — STAND BY.');const bar=document.querySelector('#reloadBar');bar.style.transition='none';bar.style.width='0%';requestAnimationFrame(()=>{bar.style.transition=`width ${total}s linear`;bar.style.width='100%';});let t=0;const timer=setInterval(()=>{t+=.1;if(!running||!reloading){clearInterval(timer);return;}if(t>=total){clearInterval(timer);ammo[weapon]=weapons[weapon].capacity;reloading=false;bar.style.transition='none';bar.style.width='0';document.querySelector('#ammo').textContent=ammo[weapon]+' / '+weapons[weapon].capacity;radio('GUN READY. KEEP THE CONVOY MOVING.');}},100);}

